/*
 * A TRAINED POLICY (PPO) playing the real Chrome dino game. Generated by scripts/export_policy_js.py;
 * do not edit the weights by hand.  Policy: __POLICY_NAME__
 *
 * HOW TO RUN
 *   1. Open the game page, DevTools (Cmd+Option+J) > Console. RELOAD the page first if an older
 *      script was pasted.
 *   2. Paste this whole file, press Enter. It prints  [dinoPolicy ...] ready  and the self-test result.
 *   3. dinoPolicy.start({ episodes: 10, maxScore: 2000 })         (score posting is BLOCKED)
 *      dinoPolicy.start({ episodes: 40, submit: 'top1' })         (posts a score above place 1 of the day)
 *   4. dinoPolicy.download() saves every episode (with a flight recorder) to a file.
 *
 * It decides about 60 times per second, exactly like the training environment (trex/real_env.py): it
 * builds the same 22 numbers from the game's own objects, runs a small neural network, and presses or
 * releases keys with real keydown/keyup events. Score posts are blocked unless you pass submit.
 */
(() => {
  const VERSION = '__VERSION__';
  const POLICY = __POLICY_JSON__;
  const SELFTEST = __SELFTEST_JSON__;
  const GROUND_Y = 93, NOSE_X = 94, START_X = 50, GROUND_BOTTOM = 140, MS_PER_FRAME = 1000 / 60;
  const KEY = { JUMP: 32, DUCK: 40, RESTART: 13 };

  // ---- the network: obs(22) -> tanh(128) -> tanh(128) -> 3 logits ----------------------------
  // weights are stored as int16 (one scale per tensor), base64-encoded, to keep this file small
  const W = (() => {
    const bin = atob(POLICY.q), n = bin.length >> 1, dv = new DataView(new ArrayBuffer(bin.length));
    for (let i = 0; i < bin.length; i++) dv.setUint8(i, bin.charCodeAt(i));
    const sizes = [POLICY.h * POLICY.n_in, POLICY.h, POLICY.h * POLICY.h, POLICY.h, 3 * POLICY.h, 3], out = [];
    let at = 0;
    sizes.forEach((sz, k) => { const a = new Float64Array(sz); for (let i = 0; i < sz; i++) a[i] = dv.getInt16((at + i) * 2, true) * POLICY.scales[k]; at += sz; out.push(a); });
    return { w1: out[0], b1: out[1], w2: out[2], b2: out[3], w3: out[4], b3: out[5] };
  })();
  function dense(x, Wm, b, nOut, nIn) {
    const y = new Float64Array(nOut);
    for (let j = 0; j < nOut; j++) { let s = b[j]; const o = j * nIn; for (let i = 0; i < nIn; i++) s += Wm[o + i] * x[i]; y[j] = s; }
    return y;
  }
  function forward(x) {
    const h1 = dense(x, W.w1, W.b1, POLICY.h, POLICY.n_in).map(Math.tanh);
    const h2 = dense(h1, W.w2, W.b2, POLICY.h, POLICY.h).map(Math.tanh);
    return dense(h2, W.w3, W.b3, 3, POLICY.h);
  }
  const argmax = (v) => (v[1] > v[0] ? (v[2] > v[1] ? 2 : 1) : (v[2] > v[0] ? 2 : 0));

  // ---- the observation: identical to RealTRexEnv._observe in Python --------------------------
  function buildObs(r, eff, dtMs, held) {
    const t = r.tRex;
    const o = new Float64Array(22);
    o[0] = (GROUND_Y - t.yPos) / 90;
    o[1] = t.jumpVelocity / 12;
    o[2] = t.jumping ? 1 : 0;
    o[3] = t.ducking ? 1 : 0;
    o[4] = t.speedDrop ? 1 : 0;
    o[5] = t.status === 'DUCKING' ? 1 : 0;
    o[6] = (r.currentSpeed - 6) / 7;
    o[7] = dtMs / MS_PER_FRAME;
    o[8] = eff / 13;
    const ahead = r.horizon.obstacles.filter((ob) => ob.xPos + ob.width > START_X).slice(0, 2);
    for (let k = 0; k < 2; k++) {
      const base = 9 + 5 * k;
      if (k < ahead.length) {
        const ob = ahead[k];
        o[base] = (ob.xPos - NOSE_X) / 600;
        o[base + 1] = ob.width / 75;
        o[base + 2] = ob.typeConfig.height / 50;
        o[base + 3] = (GROUND_BOTTOM - (ob.yPos + ob.typeConfig.height)) / 60;
        o[base + 4] = ob.typeConfig.type === 'PTERODACTYL' ? 1 : 0;
      } else { o[base] = 1.5; }
    }
    o[19 + held] = 1;
    for (let i = 0; i < 22; i++) o[i] = Math.max(-5, Math.min(5, o[i]));
    return o;
  }

  function selfTest() {
    let dl = 0, dobs = 0;
    for (const c of SELFTEST.logits) { const y = forward(Float64Array.from(c.obs)); for (let i = 0; i < 3; i++) dl = Math.max(dl, Math.abs(y[i] - c.logits[i])); }
    for (const c of SELFTEST.states) {
      const o = buildObs(c.runner, c.eff, c.dt, c.held);
      for (let i = 0; i < 22; i++) dobs = Math.max(dobs, Math.abs(o[i] - c.obs[i]));
    }
    return { maxLogitDiff: dl, maxObsDiff: dobs, ok: dl < 5e-2 && dobs < 1e-5, cases: SELFTEST.logits.length + SELFTEST.states.length };
  }

  // ---- keyboard (events, exactly like a person) ----------------------------------------------
  function key(type, code) {
    const e = new Event(type, { bubbles: true, cancelable: true });
    e.keyCode = code; e.which = code;
    document.dispatchEvent(e);
  }
  const S = { running: false, results: [], held: 0, alert0: null };
  function setHeld(next) {                    // 0 none, 1 jump held, 2 duck held: events only on changes
    if (next === S.held) return;
    if (S.held === 1) key('keyup', KEY.JUMP); else if (S.held === 2) key('keyup', KEY.DUCK);
    if (next === 1) key('keydown', KEY.JUMP); else if (next === 2) key('keydown', KEY.DUCK);
    S.held = next;
  }

  const isPlaying = (r) =>
    r.playing !== undefined ? r.playing : !!(r.isRunning && r.isRunning() && !r.crashed && r.distanceRan > 0);
  const score = (r) => Math.ceil(r.distanceMeter.getActualDistance(Math.ceil(r.distanceRan)));

  // ---- score gate: nothing reaches the leaderboard unless you say so --------------------------
  const gate = { installed: false, policy: null, blocked: [], sent: [], decisions: [], threshold: null, rank: 1 };
  const isScoreUrl = (u) => /\/inc\/set\.php/.test(String(u));
  function installGate() {
    if (gate.installed) return; gate.installed = true;
    const open = XMLHttpRequest.prototype.open, send = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.open = function (m, u, ...rest) { this.__dinoUrl = u; this.__dinoMethod = m; return open.call(this, m, u, ...rest); };
    XMLHttpRequest.prototype.send = function (body) {
      if (isScoreUrl(this.__dinoUrl) && String(this.__dinoMethod).toUpperCase() !== 'GET') {
        const rec = { url: String(this.__dinoUrl), body: String(body).slice(0, 300) };
        const posted = Number(new URLSearchParams(String(body)).get('score'));
        const ask = gate.policy ? gate.policy(posted) : { asked: false, allowed: false };
        gate.decisions.push({ score: posted, ...ask });
        if (!ask.allowed) { gate.blocked.push(rec); return; }
        gate.sent.push(rec);
      }
      return send.call(this, body);
    };
    const fetch0 = window.fetch;
    window.fetch = function (u, o) {
      if (isScoreUrl(u) && String((o && o.method) || 'GET').toUpperCase() !== 'GET') { gate.blocked.push({ url: String(u) }); return Promise.resolve(new Response('{}')); }
      return fetch0.apply(this, arguments);
    };
    const beacon0 = navigator.sendBeacon && navigator.sendBeacon.bind(navigator);
    navigator.sendBeacon = function (u, d) { if (isScoreUrl(u)) { gate.blocked.push({ url: String(u) }); return true; } return beacon0 ? beacon0(u, d) : false; };
  }
  const currentName = () => { const m = document.cookie.match(/(^| )name=([^;]+)/); return (window.user_name || (m && decodeURIComponent(m[2])) || '(no nickname set)'); };
  const hasNickname = () => !!(window.user_name || /(^| )name=[^;]+/.test(document.cookie));
  async function readPlace(n) {
    const html = await (await fetch('/', { cache: 'no-store' })).text();
    const doc = new DOMParser().parseFromString(html, 'text/html');
    const h = [...doc.querySelectorAll('h2')].find((x) => /highest scores of the day/i.test(x.textContent));
    if (!h) throw new Error('leaderboard not found on the page');
    const scores = [...h.parentElement.querySelectorAll('.result')].map((x) => Number(x.textContent.trim())).filter((x) => Number.isFinite(x));
    if (scores.length < n) return 0;
    return scores.slice(0, 5).sort((a, b) => b - a)[n - 1];
  }
  async function refreshThreshold() {
    try { const t = await readPlace(gate.rank); if (t !== gate.threshold) console.log(`[dinoPolicy] place ${gate.rank} of the day is now ${t}`); gate.threshold = t; }
    catch (e) { gate.threshold = null; console.warn('[dinoPolicy] could not read the leaderboard; posts stay blocked:', e.message); }
  }

  // ---- saved results (survive a reload) ----------------------------------------------------------
  const LOG_KEY = 'dinoPolicyLog', MAX_SAVED = 300;
  const readLog = () => { try { return JSON.parse(localStorage.getItem(LOG_KEY) || '[]'); } catch (e) { return []; } };
  function saveResult(res) {
    try { const log = readLog(); log.push({ at: new Date().toISOString(), version: VERSION, ...res }); while (log.length > MAX_SAVED) log.shift(); localStorage.setItem(LOG_KEY, JSON.stringify(log)); }
    catch (e) { console.warn('[dinoPolicy] could not save (storage full?):', e.message); }
  }
  function downloadSaved() {
    const log = readLog(); const blob = new Blob([JSON.stringify(log)], { type: 'application/json' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob);
    a.download = `dino_policy_results_${new Date().toISOString().replace(/[:.]/g, '-')}.json`;
    document.body.appendChild(a); a.click(); a.remove();
    console.log(`[dinoPolicy] saved ${log.length} episodes to ${a.download}`); return log.length;
  }

  // ---- the episode loop --------------------------------------------------------------------------
  function start(options = {}) {
    if (S.running) throw new Error('A run is already in progress. Call dinoPolicy.stop() first.');
    const { episodes = 3, submit = null, stopAt = null, maxScore: ms = null } = options;
    const maxScore = ms !== null ? ms : stopAt !== null ? stopAt : submit !== null ? Infinity : 1500;
    const rankMatch = submit === null ? null : /^top([1-5])$/.exec(String(submit));
    if (submit !== null && !rankMatch) throw new Error("submit must be 'top1' ... 'top5'");
    if (rankMatch) gate.rank = Number(rankMatch[1]);
    if (submit !== null && !hasNickname()) throw new Error('No nickname set. Click the Nickname button and set one first.');
    const Runner = window.Runner;
    if (!Runner || !Runner.instance_) throw new Error('No Runner.instance_ here: open the dino game');
    installGate();
    if (!S.alert0) { S.alert0 = window.alert; window.alert = (m) => console.log('[dinoPolicy] (site alert, not shown)', String(m).slice(0, 300)); }
    if (submit !== null) {
      gate.policy = (posted) => {
        const beats = gate.threshold !== null && posted > gate.threshold;
        console.log(beats ? `[dinoPolicy] SUBMITTING ${posted} as "${currentName()}" (place ${gate.rank} was ${gate.threshold})` : `[dinoPolicy] not submitting ${posted} (place ${gate.rank}: ${gate.threshold})`);
        return { asked: false, allowed: beats, threshold: gate.threshold };
      };
      refreshThreshold();
    } else gate.policy = null;
    S.running = true; S.results = []; S.held = 0;
    let st = null, restartAt = 0, lastKick = 0, prevTick = performance.now(), lastDist = -1, lastProgress = performance.now();
    let decisionIdx = gate.decisions.length;
    const ring = [];
    const newEpisode = (r) => ({ lastT: Date.now(), eff: r.currentSpeed, prevOb: null, prevX: 0, decisions: 0, lastAct: 0, obsum: null });
    console.log(`[dinoPolicy ${VERSION}] ${episodes} episodes; ` + (submit !== null ? `auto-submit above place ${gate.rank} as "${currentName()}"` : `cap ${maxScore}, score posts BLOCKED`));

    function finish(outcome) {
      const r = Runner.instance_;
      const res = { episode: S.results.length + 1, outcome, score: score(r), decisions: st ? st.decisions : 0, speed: +r.currentSpeed.toFixed(2), distance: Math.round(r.distanceRan) };
      const posted = gate.decisions.slice(decisionIdx).pop(); if (posted) res.posted = posted;
      decisionIdx = gate.decisions.length;
      if (outcome === 'crash' || outcome === 'stuck') res.trace = ring.slice();
      ring.length = 0; S.results.push(res); saveResult(res);
      console.log('[dinoPolicy]', JSON.stringify({ ...res, trace: undefined }));
      setHeld(0); st = null;
    }
    function tick() {
      if (!S.running) return;
      const r = Runner.instance_, now = performance.now(), wall = Date.now();
      if (now - prevTick > 500) { lastProgress = now; if (st) st.lastT = wall; }
      prevTick = now;
      if (isPlaying(r)) {
        if (r.distanceRan !== lastDist) { lastDist = r.distanceRan; lastProgress = now; }
        else if (now - lastProgress > 2500) { console.warn('[dinoPolicy] game seems frozen; logging'); finish('stuck'); lastProgress = now; key('keydown', KEY.RESTART); key('keyup', KEY.RESTART); }
      }
      if (r.crashed) {
        if (!restartAt) {
          if (st) finish('crash');
          if (S.results.length >= episodes) return done();
          restartAt = now + 1300;
          if (submit !== null) refreshThreshold();
        } else if (now >= restartAt) { key('keydown', KEY.RESTART); key('keyup', KEY.RESTART); restartAt = 0; lastDist = -1; lastProgress = now; S.held = 0; }
      } else if (!isPlaying(r)) {
        if (now - lastKick > 1000) { key('keydown', KEY.JUMP); key('keyup', KEY.JUMP); lastKick = now; }
      } else {
        if (!st) st = newEpisode(r);
        const dt = wall - st.lastT;
        if (dt >= 12) {                               // ~60 decisions per second (every 2nd frame at 120 Hz)
          const ahead = r.horizon.obstacles.filter((ob) => ob.xPos + ob.width > START_X);
          const first = ahead[0] || null;
          if (first && st.prevOb === first && dt > 0) st.eff += 0.1 * ((st.prevX - first.xPos) * MS_PER_FRAME / dt - st.eff);
          st.prevOb = first; st.prevX = first ? first.xPos : 0;
          const obs = buildObs(r, st.eff, dt, S.held);
          const act = argmax(forward(obs));
          setHeld(act);
          st.lastT = wall; st.decisions++; st.lastAct = act;
          const h = ahead[0], h2 = ahead[1];
          ring.push([st.decisions, Math.round(GROUND_Y - r.tRex.yPos), r.tRex.jumping ? 1 : 0, r.tRex.ducking ? 1 : 0, r.tRex.speedDrop ? 1 : 0, r.tRex.status[0], act,
            h ? Math.round(h.xPos - NOSE_X) : null, h ? h.typeConfig.type.slice(0, 5) + h.size : null, h2 ? Math.round(h2.xPos - NOSE_X) : null, h2 ? h2.typeConfig.type.slice(0, 5) + h2.size : null, +r.currentSpeed.toFixed(1)]);
          if (ring.length > 150) ring.shift();
        }
        if (score(r) >= maxScore) {
          setHeld(0); r.gameOver(); finish('survived');
          if (S.results.length >= episodes) return done();
          restartAt = now + 1300; if (submit !== null) refreshThreshold();
        }
      }
      requestAnimationFrame(tick);
    }
    function done() {
      S.running = false; setHeld(0);
      if (S.alert0) { window.alert = S.alert0; S.alert0 = null; }
      const crashed = S.results.filter((x) => x.outcome === 'crash').length;
      console.log(`[dinoPolicy] done: ${S.results.length - crashed} survived, ${crashed} crashed`); console.table(S.results);
    }
    requestAnimationFrame(tick);
  }
  function stop() { S.running = false; setHeld(0); if (S.alert0) { window.alert = S.alert0; S.alert0 = null; } console.log('[dinoPolicy] stopped'); }

  window.dinoPolicy = {
    version: VERSION, start, stop, forward, buildObs, selfTest, gate, readPlace,
    saved: readLog, download: downloadSaved, clearSaved() { localStorage.removeItem(LOG_KEY); },
    get results() { return S.results; }, get running() { return S.running; },
  };
  const t = selfTest();
  console.log(`[dinoPolicy ${VERSION}] ready. self-test vs Python: ${t.ok ? 'PASS' : 'FAIL'} (${t.cases} cases, max logit diff ${t.maxLogitDiff.toExponential(1)}, max obs diff ${t.maxObsDiff.toExponential(1)})`);
})();
